package com.crimescope.domain.strategy;

import java.io.Serializable;
import java.util.Map;

/**
 * Result payload generated by polymorphic analytical strategies.
 */
public class StrategyResult implements Serializable {

    private final String strategyName;
    private final String summaryDescription;
    private final Map<String, Object> numericalMetrics;
    private final Map<String, Object> visualizationData;
    private final Double calculatedIndex;

    public StrategyResult(String strategyName, String summaryDescription,
                          Map<String, Object> numericalMetrics,
                          Map<String, Object> visualizationData,
                          Double calculatedIndex) {
        this.strategyName = strategyName;
        this.summaryDescription = summaryDescription;
        this.numericalMetrics = numericalMetrics != null ? numericalMetrics : Map.of();
        this.visualizationData = visualizationData != null ? visualizationData : Map.of();
        this.calculatedIndex = calculatedIndex;
    }

    public String getStrategyName() {
        return strategyName;
    }

    public String getSummaryDescription() {
        return summaryDescription;
    }

    public Map<String, Object> getNumericalMetrics() {
        return numericalMetrics;
    }

    public Map<String, Object> getVisualizationData() {
        return visualizationData;
    }

    public Double getCalculatedIndex() {
        return calculatedIndex;
    }
}
